void AgentHost::handle_setup_check_key(const std::string& envelope_id, const std::string& payload_json)
{
    cancel_conversation_title();
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: configuring AI asked while a reply runs");
    if (!m_setup)
        throw std::logic_error("jusprin-agent-bridge: AI setup asked of a host with none");
    const json payload = json::parse(payload_json);

    SetupCredentials credentials;
    credentials.provider = payload.value("provider", "");
    credentials.api_key  = payload.value("apiKey", "");
    credentials.model    = payload.value("model", "");
    credentials.endpoint = payload.value("endpoint", "");

    // The key field sends nothing while empty.
    if (credentials.api_key.empty())
        throw RuntimeError("jusprin-agent-bridge: setup_check_key carries no key");
    if (m_setup->busy()) {
        send_bridge_error("setup_busy", translated(L("A credential check is already running.")), envelope_id);
        return;
    }

    // The pending credentials outlive the request so a verified key can be
    // persisted without the page holding or re-sending the secret.
    m_setup_pending = credentials;
    if (!m_setup->start_check(credentials)) {
        const AgentError error{"unsupported_provider",
                               translated(L("This build cannot verify a key for that provider yet.")), false};
        send_setup_status("error", envelope_id, std::nullopt, error);
        m_setup_pending.reset();
        return;
    }
    send_setup_status("checking", envelope_id);
}

void AgentHost::handle_setup_cancel()
{
    if (!m_setup || !m_setup->busy())
        return; // Cancelling a finished check is a benign race.
    m_setup->cancel();
    m_setup_pending.reset();
    send_setup_status("idle");
}

void AgentHost::handle_setup_remove_key(const std::string& envelope_id, const std::string& payload_json)
{
    // A chat title being written is not a reply; it gives way, as it does to
    // a key check.
    cancel_conversation_title();
    if (!m_setup)
        throw std::logic_error("jusprin-agent-bridge: AI setup asked of a host with none");
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: removing a key asked while a reply runs");
    // Remove is greyed out while a key is checked.
    if (m_setup->busy())
        throw RuntimeError("jusprin-agent-bridge: setup_remove_key while a key check runs");
    remove_saved_key(json::parse(payload_json).value("provider", ""));
    send_setup_keys(envelope_id);
}

void AgentHost::remove_saved_key(const std::string& provider)
{
    m_setup->remove_key(provider);
    m_rejected_keys.erase(provider);

    // The agent in use may hold the removed key. It is rebuilt from the keys
    // still stored, as a launch would build it; with none left, the dock is
    // back to being unconfigured.
    if (m_model_source) {
        AgentServicePtr agent = m_model_source->configured_providers().empty() ? nullptr :
                                m_model_source->make_agent(default_chat_model());
        const AgentAvailability availability = agent ? AgentAvailability::Ready : AgentAvailability::Unavailable;
        set_agent(std::move(agent), availability);
    } else if (m_setup->saved_keys().empty()) {
        set_agent(nullptr, AgentAvailability::Unavailable);
    }
}

void AgentHost::handle_delete_account(const std::string& envelope_id)
{
    const auto answer = [this, envelope_id](bool deleted) {
        if (m_handshake)
            send_envelope(Protocol::kAccountDeleted, json{{"deleted", deleted}}.dump(), envelope_id);
    };
    // Its key goes once the server has deleted the account, and a reply that
    // is still running would be left holding it, so one waits for the other.
    // The Preferences window asks this of a host with no chat of its own; the
    // reply runs in another host's.
    const bool reply_running = agent_busy() || (m_reply_running_elsewhere && m_reply_running_elsewhere());
    if (!m_model_source || !m_setup || reply_running || m_setup->busy()) {
        answer(false);
        return;
    }
    m_model_source->delete_account([this, answer](bool deleted) {
        if (deleted) {
            // Signed out the way Sign out does, whatever happens next: the
            // account no longer exists to sign in as.
            for (const SavedKey& saved : m_setup->saved_keys())
                if (const ProviderProfile* profile = profile_for(saved.provider); profile != nullptr && profile->account_sign_in)
                    remove_saved_key(saved.provider);
            send_setup_keys();
            request_account();
            request_account_box();
        }
        answer(deleted);
    });
}

void AgentHost::send_setup_keys(const std::string& correlation_id)
{
    if (!m_setup || !m_handshake)
        return;
    json keys = json::array();
    for (const SavedKey& saved : m_setup->saved_keys()) {
        const auto refused = m_rejected_keys.find(saved.provider);
        json key{{"provider", saved.provider}, {"hint", saved.hint},
                 {"rejected", refused != m_rejected_keys.end() && refused->second == saved.hint}};
        if (!saved.account.empty())
            key["account"] = saved.account;
        keys.push_back(std::move(key));
    }
    send_envelope(Protocol::kSetupKeys, json{{"keys", std::move(keys)}}.dump(), correlation_id);
}

void AgentHost::note_key_rejected()
{
    // Only a chat's own agent says whose key it was; a host without per-chat
    // models (the printer panel) cannot tell.
    if (m_agent_choice)
        reject_saved_key(m_agent_choice->provider);
}

void AgentHost::reject_saved_key(const std::string& provider)
{
    if (!m_setup)
        return;
    for (const SavedKey& saved : m_setup->saved_keys())
        if (saved.provider == provider) {
            m_rejected_keys[saved.provider] = saved.hint;
            send_setup_keys();
        }
}

void AgentHost::send_account_status(const std::string&               phase,
                                    const std::string&               correlation_id,
                                    const std::optional<AgentError>& error,
                                    bool                             expired)
{
    json payload{{"phase", phase}};
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud != nullptr && phase == "browser")
        payload["url"] = cloud->browser_url();
    if (const std::optional<CloudEmailStep> email = cloud != nullptr && phase == "email" ? cloud->email_step() : std::nullopt)
        payload["email"] = json{{"step", email->step == CloudEmailStep::Step::Code ? "code" : "choose"},
                                {"email", email->email},
                                {"busy", email->busy},
                                {"refusal", email->refusal},
                                {"codeResent", email->code_resent}};
    if (expired)
        payload["expired"] = true;
    if (error)
        payload["error"] = json{{"code", error->code}, {"message", error->message}, {"retryable", error->retryable}};
    send_envelope(Protocol::kAccountStatus, payload.dump(), correlation_id);
}

void AgentHost::handle_account_sign_in(const std::string& envelope_id, bool stored)
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr)
        throw std::logic_error("jusprin-agent-bridge: a sign-in asked of a host with no account sign-in");
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: signing in asked while a reply runs");
    if (m_setup->busy() || cloud->phase() != CloudSignInPhase::Idle) {
        send_bridge_error("setup_busy", translated(L("A sign-in or key check is already running.")), envelope_id);
        return;
    }
    cancel_conversation_title();
    if (stored) {
        if (!cloud->check_stored())
            throw RuntimeError("jusprin-agent-bridge: account_check with no account on this computer");
        send_account_status("checking", envelope_id);
        return;
    }
    // Idle was checked above, so start() cannot refuse; a sign-in that fails
    // to start throws.
    if (!cloud->start(CloudBrowserStart::Google))
        throw std::logic_error("An idle sign-in refused to start");
    send_account_status("browser", envelope_id);
}

void AgentHost::handle_account_email(const std::string& envelope_id, const std::string& payload_json)
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr)
        throw std::logic_error("jusprin-agent-bridge: a sign-in asked of a host with no account sign-in");
    // Only Preferences sends this, and its host runs no reply.
    if (agent_busy())
        throw RuntimeError("jusprin-agent-bridge: signing in asked while a reply runs");
    if (m_setup->busy() || cloud->phase() != CloudSignInPhase::Idle) {
        send_bridge_error("setup_busy", translated(L("A sign-in or key check is already running.")), envelope_id);
        return;
    }
    cancel_conversation_title();
    const json payload = json::parse(payload_json, nullptr, false);
    const std::string email = payload.is_object() ? payload.value("email", std::string()) : std::string();
    if (!cloud->start_email(email)) {
        send_account_status("idle", envelope_id,
                            AgentError{"sign_in_failed", translated(L("JusPrin couldn't sign you in. Try again.")), true});
        return;
    }
    send_account_status("email", envelope_id);
}

// The page offers each of these only on the step that takes it; one sent as
// the step changes under it (a double click) is refused by the sign-in and
// changes nothing.
void AgentHost::handle_account_email_step(const std::string& type, const std::string& payload_json)
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr || cloud->phase() != CloudSignInPhase::Email)
        return;
    const json payload = json::parse(payload_json, nullptr, false);
    const auto field   = [&payload](const char* name) {
        return payload.is_object() ? payload.value(name, std::string()) : std::string();
    };
    const bool taken = type == Protocol::kAccountSendCode ? cloud->send_code() :
                       type == Protocol::kAccountCode     ? cloud->submit_code(field("code")) :
                                                            cloud->submit_password(field("password"));
    // The step is now with the server: the page shows it busy.
    if (taken)
        send_account_status("email");
}

void AgentHost::handle_account_open_link(const std::string& type, const std::string& payload_json)
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr || !m_open_url)
        return;
    std::string url;
    if (type == Protocol::kAccountReopen) {
        url = cloud->browser_url();
    } else {
        const json payload = json::parse(payload_json, nullptr, false);
        url = cloud->link_url(payload.is_object() ? payload.value("link", std::string()) : std::string());
    }
    // Nothing to reopen once the browser is done, and no other page: the page
    // names a link, never a URL.
    if (!url.empty())
        m_open_url(url);
}

void AgentHost::handle_account_cancel()
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr || cloud->phase() == CloudSignInPhase::Idle)
        return; // Cancelling a finished sign-in is a benign race.
    cloud->cancel();
    send_account_status("idle");
}

void AgentHost::pump_account()
{
    ICloudSignIn* cloud = m_setup ? m_setup->cloud_sign_in() : nullptr;
    if (cloud == nullptr)
        return;
    const CloudSignInPhase before = cloud->phase();
    // The email steps move within one phase: a code asked for, refused, sent again.
    const std::optional<CloudEmailStep> email_before = cloud->email_step();
    std::optional<CloudSignInOutcome> outcome = cloud->poll();
    if (!outcome) {
        // The browser or the code came back with a token; the account is
        // being checked.
        if (before != CloudSignInPhase::Checking && cloud->phase() == CloudSignInPhase::Checking)
            send_account_status("checking");
        else if (cloud->phase() == CloudSignInPhase::Email && cloud->email_step() != email_before)
            send_account_status("email");
        return;
    }
    const std::string provider = account_provider().id;
    switch (outcome->kind) {
    case CloudSignInOutcome::Kind::SignedIn:
        m_rejected_keys.erase(provider);
        send_account_status("idle");
        send_setup_keys();
        set_agent(std::move(outcome->service), AgentAvailability::Ready);
        request_account();
        break;
    case CloudSignInOutcome::Kind::Expired:
        for (const SavedKey& saved : m_setup->saved_keys())
            if (saved.provider == provider)
                m_rejected_keys[provider] = saved.hint;
        send_account_status("idle", {}, std::nullopt, true);
        send_setup_keys();
        break;
    case CloudSignInOutcome::Kind::Failed: send_account_status("idle", {}, outcome->error); break;
    }
}

void AgentHost::pump_setup()
{
    if (!m_setup)
        return;
    // The top handlers of a sign-in and of a key check: an unexpected failure
    // stops it, which ends in error.
    try {
        pump_account();
    } catch (...) {
        if (!m_unexpected_error_handler)
            throw;
        m_unexpected_error_handler("signing in to JusPrin", std::current_exception());
        m_setup->cloud_sign_in()->cancel();
        send_account_status("idle", {}, unexpected_error());
    }
    try {
        pump_key_check();
    } catch (...) {
        if (!m_unexpected_error_handler)
            throw;
        m_unexpected_error_handler("checking an AI key", std::current_exception());
        m_setup->cancel();
        send_setup_status("error", {}, std::nullopt, unexpected_error());
        m_setup_pending.reset();
    }
}

void AgentHost::pump_key_check()
{
    std::optional<SetupOutcome> outcome = m_setup->poll();
    if (!outcome)
        return;

    if (!outcome->ok) {
        send_setup_status("error", {}, outcome->elapsed_ms, outcome->error);
        m_setup_pending.reset();
        return;
    }

    // The provider answered, so the credentials are good.
    if (m_setup_pending)
        m_setup->commit(*m_setup_pending);

    send_setup_status("verified", {}, outcome->elapsed_ms);
    if (m_setup_pending)
        m_rejected_keys.erase(m_setup_pending->provider);
    m_setup_pending.reset();
    send_setup_keys();
    // Configuration starts only between turns; messages and retries stay
    // blocked while the credential check is pending.
    set_agent(std::move(outcome->service), AgentAvailability::Ready);
}

void AgentHost::pump_tools()
{
    // A parked project boundary (Project event delivered before the new
    // directory was in place) resolves here, once per timer tick.
    m_persistence.resolve_pending_boundary();
    // A project the Agent opened is spoken about in its own chat, as one the
    // person opened is: the turn that opened it ended with the project it
    // closed, and this one starts with the report.
    while (!m_agent_opened_reports.empty()) {
        const Workspace::LoadReport report = std::move(m_agent_opened_reports.front());
        m_agent_opened_reports.pop_front();
        on_file_loaded(report);
    }
    while (!m_saved_proposals.empty()) {
        const std::string apply = std::move(m_saved_proposals.front());
        m_saved_proposals.pop_front();
        on_proposal_saved(apply);
    }
    if (std::exchange(m_check_reopened_test, false))
        tell_reopened_test();
    for (auto ended = m_ended_slices.begin(); ended != m_ended_slices.end();)
        ended = slice_ended(*ended) ? m_ended_slices.erase(ended) : std::next(ended);
    if (!m_chat_transition_blocked && m_mcp) m_mcp->poll();
    if (!m_chat_transition_blocked && (m_handshake || m_mcp))
        m_tools.pump();
    // Streaming deltas and progress mark the document dirty without forcing a
    // write each; this pump gives them their throttled flush.
    m_persistence.flush_if_dirty();
}

