void fetch_account(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                   std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<nlohmann::json>)> done)
{
    auto finished = std::make_shared<std::function<void(std::optional<nlohmann::json>)>>(std::move(done));
    auto http     = Slic3r::Http::get(account_url(profile, endpoint_override));
    http.header("Authorization", "Bearer " + api_key);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.header("Accept", "application/json")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete(reported("reading the account", [cancelled, finished](std::string body, unsigned status) {
            if (*cancelled)
                return;
            (*finished)(account_answer(status, body));
        }))
        .on_error(reported("reading the account", [cancelled, finished](std::string body, std::string, unsigned status) {
            if (!*cancelled)
                (*finished)(account_answer(status, body));
        }))
        .perform();
}

void fetch_account_box(const ProviderProfile& profile, const std::string& token, const std::string& url,
                       std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(std::optional<std::string>)> done)
{
    auto finished = std::make_shared<std::function<void(std::optional<std::string>)>>(std::move(done));
    auto http     = Slic3r::Http::get(url);
    if (!token.empty())
        http.header("Authorization", "Bearer " + token);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.header("Accept", "text/html")
        .tls_verify(true)
        .timeout_connect(10)
        .timeout_max(30)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete(reported("reading the account box", [cancelled, finished](std::string body, unsigned status) {
            if (*cancelled)
                return;
            (*finished)(account_box_answer(status, body));
        }))
        .on_error(reported("reading the account box", [cancelled, finished](std::string body, std::string, unsigned status) {
            if (*cancelled)
                return;
            // No box is shown; a server fault goes on up once that is said.
            (*finished)(std::nullopt);
            account_box_answer(status, body);
        }))
        .perform();
}

void delete_account(const ProviderProfile& profile, const std::string& token, const std::string& url,
                    std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(bool)> done)
{
    auto finished = std::make_shared<std::function<void(bool)>>(std::move(done));
    auto http     = Slic3r::Http::del(url);
    http.header("Authorization", "Bearer " + token);
    for (const AgentHttpHeader& header : profile.headers)
        http.header(header.name, header.value);
    http.tls_verify(true)
        .timeout_connect(10)
        .timeout_max(60)
        .on_progress([cancelled](Slic3r::Http::Progress, bool& cancel) { cancel = *cancelled; })
        .on_complete(reported("deleting the account", [cancelled, finished](std::string, unsigned status) {
            if (!*cancelled)
                (*finished)(status == 204);
        }))
        .on_error(reported("deleting the account", [cancelled, finished](std::string, std::string, unsigned) {
            if (!*cancelled)
                (*finished)(false);
        }))
        .perform();
}

void fetch_model_list(const ProviderProfile& profile, const std::string& api_key, const std::string& endpoint_override,
                      std::shared_ptr<std::atomic<bool>> cancelled, std::function<void(ModelListResult)> done)
{
    auto fetch       = std::make_shared<Fetch>();
    fetch->profile   = profile;
    fetch->api_key   = api_key;
    fetch->url       = model_list_url(profile, endpoint_override);
    fetch->cancelled = std::move(cancelled);
    fetch->done      = std::move(done);
    request_page(std::move(fetch), {});
}

