PreferencesWindow::~PreferencesWindow()
{
    Updates::update_check().unsubscribe(m_update_listener);
    m_pump.Stop();
    // The page's handlers call into this window, so the view goes while the
    // window is still whole rather than with wx's children after it.
    delete m_view;
}

json PreferencesWindow::state() const
{
    json payload = snapshot(*wxGetApp().app_config, current_facts());
    payload["section"] = m_request.section.empty() ? "account" : m_request.section;
    payload["closeWhenDone"] = m_request.close_when_done;
    return payload;
}

bool PreferencesWindow::page_connected() const
{
    return m_view != nullptr && m_view->host().handshake_complete();
}

void PreferencesWindow::push_state()
{
    if (m_view != nullptr && m_view->host().handshake_complete())
        m_view->host().send_page_envelope(Agent::Protocol::kPreferences, state());
}

bool PreferencesWindow::on_page_message(const std::string& type, const json& payload)
{
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "close") {
        // The page closes a window opened for one task once it is done. A key
        // counts only once one is stored and the agent is on.
        AfterClose after;
        const std::string done = payload.value("done", std::string());
        if (m_request.close_when_done &&
            (done == "tool" || (done == "key" && wxGetApp().app_config->get("jusprin_agent", "enabled") == "true")))
            after.done = done;
        CallAfter(reported("closing Preferences", [this, after] { close_for(after); }));
        return true;
    }
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "open_server_page") {
        // Account's Get more credits, in the sheet the composer's opens,
        // here over this window. This page reads the balance again after; the
        // main window's screens read it when they come back on screen.
        const std::string page = payload.value("page", std::string());
        const std::string from = payload.value("from", std::string());
        CallAfter(reported("opening an account page", [this, page, from] {
            ServerSheet::open(this, page, from, [this] {
                if (m_view != nullptr)
                    m_view->host().refresh_account();
            });
        }));
        return true;
    }
    if (type == Agent::Protocol::kShellAction && payload.is_object() && payload.value("action", std::string()) == "check_for_updates") {
        // Account's Get the new version…: the page turns to Updates itself.
        // This window is the Preferences that would be opened, so only the
        // check happens, and its answer reaches Updates as any check's does.
        get_new_version();
        return true;
    }
    if (type != Agent::Protocol::kPreferencesAction)
        return false;
    const Outcome outcome = apply_action(*wxGetApp().app_config, payload);
    // Crashes go only while automatic reports are on.
    sentry_follow_setting(wxGetApp().app_config->get_bool(kReportErrorsKey));
    if (!outcome.error.empty())
        BOOST_LOG_TRIVIAL(warning) << "JusPrin Preferences refused an action: " << outcome.error;
    // The page draws what is stored, so a refused change springs back.
    push_state();
    if (outcome.error.empty() && outcome.effect != Effect::None) {
        // Not from inside the web view's message handler: some of these open
        // a modal dialog or close this window.
        CallAfter(reported("closing Preferences", [this, outcome] { carry_out(outcome); }));
    }
    return true;
}

