void ProviderKeySetup::cancel()
{
    if (m_candidate)
        m_candidate->cancel();
    m_candidate.reset();
}

std::optional<SetupOutcome> ProviderKeySetup::poll()
{
    if (!m_candidate)
        return std::nullopt;

    while (const std::optional<AgentEvent> event = m_candidate->poll()) {
        switch (event->kind) {
        case AgentEventKind::TextDelta:
            break; // What it says is irrelevant; that it answers is the test.
        case AgentEventKind::ToolCall:
        case AgentEventKind::Completed:
            // Either way the provider accepted the credentials and replied.
            return finish_ok();
        case AgentEventKind::Failed: {
            SetupOutcome outcome;
            outcome.error =
                event->error.value_or(AgentError{"setup_failed", translated(L("The provider did not answer.")), true});
            outcome.elapsed_ms = elapsed_ms();
            cancel();
            return outcome;
        }
        }
    }
    return std::nullopt;
}

void ProviderKeySetup::commit(const SetupCredentials& credentials)
{
    m_commit(credentials);
}

std::vector<SavedKey> ProviderKeySetup::saved_keys() const
{
    std::vector<SavedKey> saved;
    if (!m_keys.load)
        return saved;
    for (const ProviderProfile& profile : provider_profiles()) {
        const std::string key = m_keys.load(profile.id);
        if (key.empty())
            continue;
        SavedKey entry{profile.id, api_key_hint(profile.id, key), {}};
        if (profile.account_sign_in && m_cloud)
            if (const std::optional<CloudAccountRecord> account = m_cloud->account())
                entry.account = account->email;
        saved.push_back(std::move(entry));
    }
    return saved;
}
